use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set so the
/// value cannot alter the query string or the host.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// One enrichment fetch per run.
///
/// Assumption: `RunInfo` has no text field. Its only textual field is `date`,
/// so `date` is used as the `q` input. If the platform team meant a different
/// field, change the argument below.
///
/// `fetch` is used rather than `get` so a transport failure comes back as a
/// value. The result is discarded, so the output does not depend on the
/// enrichment. An out-of-allowlist host still traps at the boundary.
fn enrich(info: &RunInfo) {
    let url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        enrich(&info);

        // Assumption: the subscriptions store holds one newline-separated list
        // of URLs under the key "urls". If the key is missing, the result is
        // an empty list.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
